function phu17ChiCung(lasoData, tenCung) {
    if (!lasoData || !lasoData.lasoOb) return "";
    for (let i = 0; i < lasoData.lasoOb.length; i++) {
        if (lasoData.lasoOb[i].tenCung === tenCung) return lasoData.lasoOb[i].chi;
    }
    return "";
}
